<script>
const image=document.getElementById('image'),preview=document.getElementById('preview'),drop=document.getElementById('drop');
image.addEventListener('change',()=>{const f=image.files[0];if(f){preview.src=URL.createObjectURL(f);preview.style.display='block'}});
['dragenter','dragover'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>{if(e.dataTransfer.files.length){image.files=e.dataTransfer.files;image.dispatchEvent(new Event('change'))}});
document.getElementById('form').addEventListener('submit',async e=>{e.preventDefault();const btn=document.getElementById('submit');btn.disabled=true;btn.textContent='ANALYZING CHART…';try{const r=await fetch('analyze.php',{method:'POST',body:new FormData(e.target)});const data=await r.json();document.getElementById('result').style.display='block';document.getElementById('analysis').textContent=data.analysis||data.error||'No analysis returned.';document.getElementById('meta').innerHTML='<span class="pill">'+(data.symbol||'Chart')+'</span><span class="pill">'+(data.timeframe||'Unknown TF')+'</span><span class="pill">'+(data.engine||'AI')+'</span>';document.getElementById('result').scrollIntoView({behavior:'smooth'});}catch(err){document.getElementById('result').style.display='block';document.getElementById('analysis').textContent='Connection error: '+err.message}finally{btn.disabled=false;btn.textContent='ANALYZE MARKET'}});
</script>
